namespace Xunit.Asserts.Compare.Tests.UseCases;

/// <summary>
/// One test per recipe in docs/use-cases.md. Keep the two in sync.
/// </summary>
public class UseCaseSamples
{
    // 1. Ignore values generated by the system (ids, timestamps)
    [Fact]
    public void Ignore_generated_ids_and_timestamps()
    {
        var actual = CustomerService.Register("Jacob", "jacob@example.com", "Hanoi");

        var expected = new Customer
        {
            Name = "Jacob",
            Email = "jacob@example.com",
            ShippingAddress = new Address { Street = "1 Main St", City = "Hanoi", Country = "VN" },
        };

        DeepAssert.Equal(expected, actual, o => o.Ignore(c => c.Id, c => c.CreatedAt, c => c.UpdatedAt));
    }

    [Fact]
    public void Ignore_by_wildcard()
    {
        var actual = CustomerService.Register("Jacob", "jacob@example.com", "Hanoi");
        var expected = new Customer
        {
            Name = "Jacob",
            Email = "jacob@example.com",
            ShippingAddress = new Address { Street = "1 Main St", City = "Hanoi", Country = "VN" },
        };

        DeepAssert.Equal(expected, actual, o => o.Ignore("Id", "*At"));
    }

    // 2. Ignore a whole nested type (audit info, metadata)
    [Fact]
    public void Ignore_a_nested_type()
    {
        var expected = new Invoice { Number = "INV-1", Total = 100m, Audit = new AuditTrail { CreatedBy = "alice" } };
        var actual = new Invoice { Number = "INV-1", Total = 100m, Audit = new AuditTrail { CreatedBy = "system", CreatedAt = DateTime.UtcNow } };

        DeepAssert.Equal(expected, actual, o => o.IgnoreType<AuditTrail>());
    }

    // 3. Check a mapping or API response against an anonymous object
    [Fact]
    public void Check_a_mapping_with_an_anonymous_object()
    {
        var customer = CustomerService.Register("Jacob", "jacob@example.com", "Hanoi");

        var dto = CustomerService.ToDto(customer);

        DeepAssert.Equivalent(new { Name = "Jacob", Email = "jacob@example.com", City = "Hanoi" }, dto);
    }

    [Fact]
    public void Check_only_the_members_you_care_about()
    {
        var customer = CustomerService.Register("Jacob", "jacob@example.com", "Hanoi");

        // Members that exist only on the actual object (Id, CreatedAt, Lines, ...) are not checked.
        DeepAssert.Equivalent(new { Name = "Jacob", ShippingAddress = new { City = "Hanoi" } }, customer);
    }

    // 4. Compare query results whose order is not guaranteed
    [Fact]
    public void Ignore_collection_order()
    {
        var expected = new List<OrderLine>
        {
            new() { Sku = "BOOK", Quantity = 1, UnitPrice = 12.50m },
            new() { Sku = "PEN", Quantity = 10, UnitPrice = 1.20m },
        };

        DeepAssert.Equal(expected, CustomerService.LoadLines(), o => o.IgnoreCollectionOrder());
    }

    [Fact]
    public void Match_collection_items_by_key()
    {
        var expected = new List<OrderLine>
        {
            new() { Sku = "BOOK", Quantity = 1, UnitPrice = 12.50m },
            new() { Sku = "PEN", Quantity = 10, UnitPrice = 1.20m },
        };

        // Items are paired by Sku, so a failure says "PEN.Quantity differs" instead of "item not found".
        DeepAssert.Equal(expected, CustomerService.LoadLines(), o => o.MatchCollectionItemsBy<OrderLine>(l => l.Sku));
    }

    // 5. Accept rounding and clock differences
    [Fact]
    public void Allow_numeric_and_time_tolerances()
    {
        var now = DateTime.UtcNow;
        var expected = new Invoice { Number = "INV-1", TaxRate = 0.1, Total = 110.00m, IssuedAt = now };
        var actual = new Invoice { Number = "INV-1", TaxRate = 0.1 + 1e-12, Total = 110.004m, IssuedAt = now.AddMilliseconds(250) };

        DeepAssert.Equal(expected, actual, o => o
            .WithDoubleTolerance(1e-9)
            .WithDecimalTolerance(0.01m)
            .WithDateTimeTolerance(TimeSpan.FromSeconds(1)));
    }

    // 6. Relax string comparison
    [Fact]
    public void Relax_string_comparison()
    {
        var expected = new CustomerDto { Name = "Jacob", Email = "JACOB@EXAMPLE.COM", City = null };
        var actual = new CustomerDto { Name = " Jacob ", Email = "jacob@example.com", City = "" };

        DeepAssert.Equal(expected, actual, o => o
            .IgnoreCase()
            .IgnoreLeadingTrailingWhitespace()
            .TreatNullAndEmptyStringAsEqual());
    }

    // 7. Look for an item in a collection
    [Fact]
    public void Find_an_item_in_a_collection()
    {
        var lines = CustomerService.LoadLines();

        DeepAssert.Contains(new OrderLine { Sku = "BOOK", Quantity = 1, UnitPrice = 12.50m }, lines);
        DeepAssert.DoesNotContain(new OrderLine { Sku = "BOOK", Quantity = 2, UnitPrice = 12.50m }, lines);
        DeepAssert.Contains(new OrderLine { Sku = "PEN" }, lines, o => o.CompareOnly(l => l.Sku));
    }

    // 8. Plug in custom equality for one type
    [Fact]
    public void Use_a_custom_comparer()
    {
        var expected = new Customer { Name = "Jacob", Email = "jacob@example.com", ShippingAddress = new Address { City = "Hanoi" } };
        var actual = new Customer { Name = "Jacob", Email = "jacob@example.com", ShippingAddress = new Address { City = "HANOI", Street = "ignored" } };

        DeepAssert.Equal(expected, actual, o => o
            .WithComparer<Address>((a, b) => string.Equals(a.City, b.City, StringComparison.OrdinalIgnoreCase)));
    }

    // 9. Share one set of options across tests
    private static readonly Action<DeepAssertOptions<Customer>> IgnoreGenerated =
        o => o.Ignore(c => c.Id, c => c.CreatedAt, c => c.UpdatedAt);

    [Fact]
    public void Reuse_options()
    {
        var first = CustomerService.Register("Jacob", "jacob@example.com", "Hanoi");
        var second = CustomerService.Register("Jacob", "jacob@example.com", "Hanoi");

        DeepAssert.Equal(first, second, IgnoreGenerated);
    }

    // 10. Drop down to CompareNETObjects for anything else
    [Fact]
    public void Configure_compare_net_objects_directly()
    {
        var expected = new Customer { Name = "Jacob", Lines = [new OrderLine { Sku = "PEN" }] };
        var actual = new Customer { Name = "Jacob", Lines = [] };

        DeepAssert.Equal(expected, actual, o => o.Configure(config => config.TypesToIgnore.Add(typeof(List<OrderLine>))));
    }
}
